    public function fetch_markets($params = array()): array {
        /**
         * maps the top uniswap v4 $pools by TVL to ccxt spot markets, one $market per token pair
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing $market $data
         */
        $limit = $this->safe_integer($this->options, 'marketsLimit', 100);
        $request = array(
            'query' => 'query ($first => Int!) array( $pools(first => $first, orderBy => totalValueLockedUSD, orderDirection => desc) array( id feeTier tickSpacing hooks totalValueLockedUSD token0 array( id $symbol decimals ) token1 array( id $symbol decimals ) ) )',
            'variables' => array( 'first' => $limit ),
        );
        $response = $this->subgraphPostGraphql($this->extend($request, $params));
        $data = $this->safe_dict($response, 'data', array());
        $pools = $this->safe_list($data, 'pools', array());
        // v4 allows unlimited pools per pair (fee tier x tick spacing x hook contract), but a ccxt symbol must be unique.
        // ponytail: keep only the deepest pool per pair, the trading api routes across all of them anyway
        $result = array();
        $seen = array();
        for ($i = 0; $i < count($pools); $i++) {
            $market = $this->parse_market($pools[$i]);
            $symbol = $this->safe_symbol(null, $market);
            if (!(is_array($seen) && array_key_exists($symbol ?? '', $seen))) {
                $seen[$symbol] = true;
                $result[] = $market;
            }
        }
        return $result;
    }

    public function parse_market(array $pool): array {
        //
        //     {
        //         "id": "0x21c67e77068de97969ba93d4aab21826d33ca12bb9f565d8496e8fda8a82ca27", // bytes32 PoolId
        //         "feeTier": "500",
        //         "tickSpacing": "10",
        //         "hooks": "0x0000000000000000000000000000000000000000",
        //         "totalValueLockedUSD": "123456789.12",
        //         "token0": { "id": "0x0000000000000000000000000000000000000000", "symbol": "ETH", "decimals": "18" }, // native eth
        //         "token1": { "id": "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48", "symbol": "USDC", "decimals": "6" }
        //     }
        //
        // WARNING: token symbols are not unique on-chain, anyone can deploy a token called USDC.
        // TVL ordering filters most spam, but callers must check baseId/quoteId (the token addresses) before trading.
        $token0 = $this->safe_dict($pool, 'token0', array());
        $token1 = $this->safe_dict($pool, 'token1', array());
        $baseId = $this->safe_string_lower($token0, 'id');
        $quoteId = $this->safe_string_lower($token1, 'id');
        $base = $this->safe_string_upper($token0, 'symbol');
        $quote = $this->safe_string_upper($token1, 'symbol');
        $fee = Precise::string_div($this->safe_string($pool, 'feeTier'), '1000000'); // hundredths of a bip
        return $this->safe_market_structure(array(
            'id' => $this->safe_string($pool, 'id'),
            'symbol' => $base . '/' . $quote,
            'base' => $base,
            'quote' => $quote,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'type' => 'spot',
            'spot' => true,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'active' => true,
            'contract' => false,
            'taker' => $this->parse_number($fee),
            'maker' => $this->parse_number($fee), // LPs are the makers, a swapper always pays the pool fee
            'precision' => array(
                'amount' => $this->parse_number($this->parse_precision($this->safe_string($token0, 'decimals'))),
                'price' => null,
            ),
            'limits' => array(
                'amount' => array( 'min' => null, 'max' => null ),
                'price' => array( 'min' => null, 'max' => null ),
                'cost' => array( 'min' => null, 'max' => null ),
                'leverage' => array( 'min' => null, 'max' => null ),
            ),
            'created' => null,
            'info' => $pool,
        ));
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): array {
        /**
         * builds an unsigned $swap transaction, it does NOT execute anything
         *
         * @see https://api-docs.uniswap.org/introduction
         *
         * @param {string} $symbol unified $symbol of the $market
         * @param {string} $type must be 'market', v4 has no native limit orders
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount amount of the base currency to buy or sell
         * @param {float} [$price] ignored
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->swapper] address that will sign and send the tx, defaults to $this->walletAddress
         * @param {float} [$params->slippageTolerance] percent, defaults to $this->options.slippageTolerance
         * @return {array} an ~@link https://docs.ccxt.com/?id=order-structure order structure~ with status null and the unsigned tx in info.swap
         */
        if ($type !== 'market') {
            throw new InvalidOrder($this->id . ' createOrder() supports $market orders only, limit orders on v4 need a limit-order hook');
        }
        $this->load_markets();
        $market = $this->market($symbol);
        $swapper = $this->safe_string($params, 'swapper', $this->walletAddress);
        if ($swapper === null) {
            throw new ArgumentsRequired($this->id . ' createOrder() requires $this->walletAddress or $params->swapper');
        }
        $decimals = $this->safe_string($this->safe_dict($market['info'], 'token0', array()), 'decimals');
        // amount / 10^-decimals with precision 0 = integer base units (wei), truncated
        $rawAmount = Precise::string_div($this->number_to_string($amount), $this->parse_precision($decimals), 0);
        $chainId = $this->safe_integer($this->options, 'chainId');
        $isSell = ($side === 'sell');
        // sell = spend exactly `amount` base, buy = receive exactly `amount` base
        $quoteRequest = array(
            'type' => $isSell ? 'EXACT_INPUT' : 'EXACT_OUTPUT',
            'amount' => $rawAmount,
            'tokenInChainId' => $chainId,
            'tokenOutChainId' => $chainId,
            'tokenIn' => $isSell ? $market['baseId'] : $market['quoteId'],
            'tokenOut' => $isSell ? $market['quoteId'] : $market['baseId'],
            'swapper' => $swapper,
            'protocols' => array( 'V4' ),
            'slippageTolerance' => $this->safe_number($params, 'slippageTolerance', $this->safe_number($this->options, 'slippageTolerance')),
        );
        $quote = $this->tradingPostQuote($quoteRequest);
        // if the quote carries permitData the caller must sign that Permit2 message first
        // and pass { 'signature': ... } back, we cannot do it without the private key
        $signature = $this->safe_string($params, 'signature');
        $swapRequest = array( 'quote' => $this->safe_dict($quote, 'quote') );
        $permitData = $this->safe_dict($quote, 'permitData');
        if ($permitData !== null && $signature !== null) {
            $swapRequest['permitData'] = $permitData;
            $swapRequest['signature'] = $signature;
        }
        $swap = $this->tradingPostSwap($swapRequest);
        //
        //     { "swap": { "to": "0x66a9...", "from": "0x...", "data": "0x3593...", "value": "0", "chainId": 1, "gasLimit": "250000" } }
        //
        return $this->safe_order(array(
            'id' => null, // becomes the tx hash once broadcast
            'symbol' => $market['symbol'],
            'type' => 'market',
            'side' => $side,
            'amount' => $amount,
            'status' => null, // nothing happened on-chain yet
            'info' => array(
                'quote' => $quote,
                'permitData' => $permitData,
                'swap' => $this->safe_dict($swap, 'swap'),
            ),
        ), $market);
    }

    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array()): array {
        /**
         * not supported, an AMM has a continuous price curve, not discrete resting orders
         * @param {string} $symbol unified $symbol of the market
         * @param {int} [$limit] ignored
         * @param {array} [$params] ignored
         * @return {array} never returns
         */
        throw new NotSupported($this->id . ' fetchOrderBook() is not supported, use createOrder() quotes for executable prices');
    }

    public function sign(mixed $path, mixed $api = 'trading', $method = 'POST', $params = array(), ?array $headers = null, ?string $body = null) {
        $url = null;
        $headers = array( 'Content-Type' => 'application/json' );
        if ($api === 'subgraph') {
            $graphApiKey = $this->safe_string($this->options, 'graphApiKey');
            if ($graphApiKey === null) {
                throw new ArgumentsRequired($this->id . ' requires exchange.options["graphApiKey"] (a The Graph gateway key) to fetch markets');
            }
            $url = $this->implode_params($this->urls['api']['subgraph'], array(
                'apiKey' => $graphApiKey,
                'subgraphId' => $this->safe_string($this->options, 'subgraphId'),
            ));
        } else {
            $this->check_required_credentials();
            $url = $this->urls['api']['trading'] . '/' . $path;
            $headers['X-API-KEY'] = $this->apiKey;
        }
        $body = $this->json($params);
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function handle_errors(int $httpCode, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($response === null) {
            return null;
        }
        // graphql returns http 200 with an errors array, the trading api returns { errorCode, detail }
        $errors = $this->safe_list($response, 'errors');
        $errorCode = $this->safe_string($response, 'errorCode');
        if ($errors !== null || $errorCode !== null) {
            throw new ExchangeError($this->id . ' ' . $body);
        }
        return null;
    }
